namespace TrStudio.Models.Contracts;

/// <summary>
/// Filter/paging options for gallery asset listings (<c>GET /api/v1/assets</c>).
/// </summary>
public class AssetFilterRequest
{
    /// <summary>Free-text search over asset metadata, if provided.</summary>
    public string? Search { get; set; }

    /// <summary>Restrict to a media kind (<c>image</c>, <c>video</c>, <c>audio</c>), if provided.</summary>
    public string? Kind { get; set; }

    /// <summary>Restrict to assets generated by a specific registry model, if provided.</summary>
    public string? ModelId { get; set; }

    /// <summary>Restrict to assets belonging to a specific project, if provided.</summary>
    public Guid? ProjectId { get; set; }

    /// <summary>The 1-based page number to return.</summary>
    public int Page { get; set; } = 1;

    /// <summary>The page size to return.</summary>
    public int PageSize { get; set; } = 50;
}
